INSERT INTO `company_technical_questions` (`question_id`, `company_id`, `category`, `question_type`, `question`, `code_snippet`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `expected_output`, `explanation`, `difficulty`, `active`) VALUES
(1, 0, 'Python', 'output_prediction', 'What will be the output of this Python program?', 'x = 5\ny = 3\nprint(x + y * 2)', '', '', '', '', '11', '11', 'Due to operator precedence, y * 2 evaluates to 6 first, and 5 + 6 equals 11.', 'Easy', 1),
(2, 1, 'Python', 'output_prediction', 'What is the output of the following slice operation?', 's = \'PLACEMENT\'\nprint(s[1:5])', '', '', '', '', 'LACE', 'LACE', 'String slicing s[1:5] extracts characters from index 1 to 4: L-A-C-E.', 'Easy', 1),
(3, 2, 'Python', 'output_prediction', 'What will be printed by this code snippet?', 'nums = [1, 2, 3, 4, 5]\nres = [x * 2 for x in nums if x % 2 == 0]\nprint(res)', '', '', '', '', '[4, 8]', '[4, 8]', 'Only even numbers (2, 4) satisfy the condition, multiplied by 2 gives [4, 8].', 'Medium', 1),
(4, 3, 'Python', 'output_prediction', 'Predict the output of the dictionary operation:', 'd = {\'a\': 1, \'b\': 2}\nd[\'a\'] = d.get(\'a\', 0) + 10\nprint(d[\'a\'])', '', '', '', '', '11', '11', 'd.get(\'a\', 0) returns 1; 1 + 10 = 11, which updates key \'a\'.', 'Easy', 1),
(5, 13, 'C/C++', 'output_prediction', 'What will be the output of this C code snippet?', '#include <stdio.h>\nint main() {\n    int a = 10;\n    int *ptr = &a;\n    *ptr += 5;\n    printf(\"%d\", a);\n    return 0;\n}', '', '', '', '', '15', '15', '*ptr modifies the value of variable \'a\' directly in memory to 10 + 5 = 15.', 'Medium', 1),
(6, 4, 'Java', 'output_prediction', 'What will be the output of this Java code snippet?', 'String str = \"Hello\";\nstr.concat(\" World\");\nSystem.out.println(str);', '', '', '', '', 'Hello', 'Hello', 'Strings are immutable in Java. concat() returns a new string, leaving original \'str\' unchanged.', 'Medium', 1),
(7, 10, 'Algorithms', 'output_prediction', 'What will be printed when func(4) is executed?', 'def func(n):\n    if n <= 1:\n        return 1\n    return n + func(n - 1)\n\nprint(func(4))', '', '', '', '', '10', '10', 'func(4) = 4 + func(3) = 4 + 3 + func(2) = 4 + 3 + 2 + 1 = 10.', 'Medium', 1),
(8, 0, 'Data Structures', 'mcq', 'Which data structure operates strictly on the FIFO (First-In-First-Out) principle?', NULL, 'Stack', 'Queue', 'Binary Search Tree', 'Priority Queue', 'B', '', 'A Queue maintains First-In-First-Out (FIFO) ordering where elements are inserted at rear and removed from front.', 'Easy', 1),
(9, 1, 'Data Structures', 'mcq', 'Which of the following problems is most efficiently solved using a Stack data structure?', NULL, 'Balanced Parentheses checking', 'Breadth-First Search', 'Round Robin CPU Scheduling', 'Priority Job Dispatch', 'A', '', 'Checking balanced parentheses utilizes a LIFO Stack to match closing symbols with the most recent open symbol.', 'Easy', 1),
(10, 2, 'Data Structures', 'mcq', 'Performing an Inorder traversal on a Binary Search Tree (BST) visits the node keys in:', NULL, 'Reverse sorted order', 'Strictly ascending sorted order', 'Level-by-level order', 'Random hashing order', 'B', '', 'Inorder traversal (Left, Root, Right) on a valid BST always produces keys in non-decreasing sorted order.', 'Easy', 1),
(11, 10, 'Algorithms', 'mcq', 'What is the average time complexity of searching for an element in a balanced Binary Search Tree (AVL / Red-Black)?', NULL, 'O(1)', 'O(log n)', 'O(n)', 'O(n log n)', 'B', '', 'Because tree height is bounded by O(log n), search, insert, and delete take O(log n) average time.', 'Medium', 1),
(12, 3, 'Algorithms', 'mcq', 'Which comparison-based sorting algorithm has a guaranteed worst-case time complexity of O(n log n)?', NULL, 'Quick Sort', 'Merge Sort', 'Bubble Sort', 'Insertion Sort', 'B', '', 'Merge Sort repeatedly divides and merges arrays in guaranteed O(n log n) time in all cases (best, average, worst).', 'Medium', 1),
(13, 0, 'SQL', 'mcq', 'Which SQL clause is used to filter aggregated data generated by a GROUP BY clause?', NULL, 'WHERE', 'ORDER BY', 'HAVING', 'DISTINCT', 'C', '', 'The HAVING clause filters grouped summary records, whereas WHERE filters individual rows prior to aggregation.', 'Easy', 1),
(14, 4, 'SQL', 'mcq', 'Which SQL JOIN returns all rows from the left table, and matching records from the right table?', NULL, 'INNER JOIN', 'RIGHT JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'C', '', 'A LEFT JOIN returns all rows from the left-hand table, filling unmatched right-hand columns with NULL.', 'Easy', 1),
(15, 0, 'DBMS', 'mcq', 'In database transaction management, the \'I\' in ACID stands for:', NULL, 'Integrity', 'Isolation', 'Inheritance', 'Indexing', 'B', '', 'ACID stands for Atomicity, Consistency, Isolation, and Durability.', 'Easy', 1),
(16, 1, 'DBMS', 'mcq', 'Which constraint combination uniquely defines a Primary Key in relational database design?', NULL, 'UNIQUE and NULLABLE', 'UNIQUE and NOT NULL', 'FOREIGN KEY and DEFAULT', 'CHECK and AUTO_INCREMENT', 'B', '', 'A Primary Key uniquely identifies each row and strictly forbids NULL values (UNIQUE + NOT NULL).', 'Easy', 1),
(17, 0, 'OOP', 'mcq', 'Which concept allows a single function name or operator to possess different behaviors depending on parameters?', NULL, 'Encapsulation', 'Polymorphism', 'Abstraction', 'Inheritance', 'B', '', 'Polymorphism allows methods or operators to take many forms (e.g. method overloading and overriding).', 'Easy', 1),
(18, 2, 'OOP', 'mcq', 'Which type of inheritance is NOT directly supported by classes in Java to avoid ambiguity (diamond problem)?', NULL, 'Single Inheritance', 'Multilevel Inheritance', 'Hierarchical Inheritance', 'Multiple Inheritance', 'D', '', 'Java does not allow a class to extend multiple classes directly to prevent the Diamond Problem; interfaces are used instead.', 'Medium', 1),
(19, 0, 'Operating Systems', 'mcq', 'Which of the following is NOT one of the Coffman conditions required for a deadlock to occur?', NULL, 'Mutual Exclusion', 'Hold and Wait', 'Preemption Allowed', 'Circular Wait', 'C', '', 'No Preemption is the necessary condition. If resources can be preempted, deadlock is prevented.', 'Medium', 1),
(20, 3, 'Operating Systems', 'mcq', 'Thrashing in an operating system occurs when:', NULL, 'CPU operates at 100% compute load', 'The system spends more time paging than executing processes', 'Deadlock occurs between two threads', 'A process terminates abnormally', 'B', '', 'Thrashing happens when excessive page faults force the OS to spend more time swapping pages than executing user code.', 'Medium', 1),
(21, 0, 'Computer Networks', 'mcq', 'At which layer of the OSI model do routers primarily operate to forward packets across networks?', NULL, 'Data Link Layer (Layer 2)', 'Network Layer (Layer 3)', 'Transport Layer (Layer 4)', 'Application Layer (Layer 7)', 'B', '', 'Routers inspect logical IP addresses and operate at the Network Layer (Layer 3) to route packets.', 'Easy', 1),
(22, 10, 'Computer Networks', 'mcq', 'Which transport protocol provides connection-oriented, reliable, acknowledged byte-stream delivery?', NULL, 'UDP', 'IP', 'TCP', 'ICMP', 'C', '', 'TCP (Transmission Control Protocol) establishes a 3-way handshake and guarantees in-order reliable delivery.', 'Easy', 1),
(23, 0, 'Web Development', 'mcq', 'What HTTP status code represents \'201 Created\' in a RESTful Web API?', NULL, '200', '201', '204', '301', 'B', '', 'HTTP status code 201 indicates that the request succeeded and led to the creation of a new resource.', 'Easy', 1),
(24, 0, 'Web Development', 'mcq', 'In the standard CSS Box Model, which layer sits immediately between the content and the border?', NULL, 'Margin', 'Padding', 'Outline', 'Box-shadow', 'B', '', 'The CSS Box Model comprises Content -> Padding -> Border -> Margin.', 'Easy', 1),
(25, 0, 'Python', 'output_prediction', 'What is the output of this Python code?', 'words = [\'Cloud\', \'AI\', \'ML\']\nprint(\'-\'.join(words))', '', '', '', '', 'Cloud-AI-ML', 'Cloud-AI-ML', 'The join() method concatenates list elements separated by the hyphen \'-\' delimiter.', 'Easy', 1),
(26, 13, 'Problem Solving', 'output_prediction', 'What is the output of this integer division logic in Python?', 'a = 17 // 3\nb = 17 % 3\nprint(f\'{a},{b}\')', '', '', '', '', '5,2', '5,2', 'Integer floor division 17 // 3 yields 5; remainder 17 % 3 yields 2. Result is 5,2.', 'Easy', 1),
(27, 1, 'Programming', 'output_prediction', 'What will be the output of this list mutation in Python?', 'a = [10, 20, 30]\nb = a\nb.append(40)\nprint(len(a))', '', '', '', '', '4', '4', 'Variables \'a\' and \'b\' reference the exact same list object in memory; modifying \'b\' mutates \'a\' as well.', 'Medium', 1),
(28, 2, 'Problem Solving', 'output_prediction', 'What boolean value will be printed by this logical condition?', 'x = (5 > 2) and not (3 == 4 or 1 > 5)\nprint(x)', '', '', '', '', 'True', 'True', '(5 > 2) is True. (3 == 4 or 1 > 5) is False. not(False) is True. True and True yields True.', 'Easy', 1),
(29, 10, 'Data Structures', 'mcq', 'Which collision resolution technique uses linked lists to chain elements sharing the same hash index?', NULL, 'Linear Probing', 'Quadratic Probing', 'Separate Chaining', 'Double Hashing', 'C', '', 'Separate Chaining stores colliding entries in a linked list attached to each bucket of the hash table.', 'Medium', 1),
